export type NotificationPreference = {
  enabled: boolean
}

let enabled = false

export function getNotificationPreference(): NotificationPreference {
  return { enabled }
}

export function toggleNotificationPreference(): NotificationPreference {
  enabled = !enabled
  return { enabled }
}

import { toggleNotificationPreferenceAction } from './actions'
import { getNotificationPreference } from '@/lib/notifications'

export default function Home() {
  const { enabled } = getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are {enabled ? 'on' : 'off'}.</p>
      <form action={toggleNotificationPreferenceAction}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}
